type PageViewEvent = {
  event: 'page_view'
  path: string
  timestamp: string
}

export async function logPageView(path: string): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    throw new Error('ANALYTICS_ENDPOINT is required to log page views')
  }

  const event: PageViewEvent = {
    event: 'page_view',
    path,
    timestamp: new Date().toISOString(),
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(process.env.ANALYTICS_API_KEY
        ? { Authorization: `Bearer ${process.env.ANALYTICS_API_KEY}` }
        : {}),
    },
    body: JSON.stringify(event),
    cache: 'no-store',
  })

  if (!response.ok) {
    throw new Error(`Analytics service rejected page view: HTTP ${response.status}`)
  }
}
